package enrollment

import (
 "context"
 "crypto/sha256"
 "database/sql"
 "errors"
 "fmt"

 "github.com/wayne47188/Alpha-Pentas/manager/internal/identity"
)

var ErrClaimConflict = errors.New("enrollment claim conflicts with existing identity")

// Claim atomically consumes a project-bound token and reserves an Agent
// identity. Certificate signing and finalization are separate recoverable steps.
// UUIDs must be generated by the trusted caller and validated at the API edge.
func (s SQLStore) Claim(ctx context.Context, token, projectID, agentID, claimID string, csrDER []byte) error {
 if s.DB == nil { return errors.New("nil database") }
 if token == "" || projectID == "" || agentID == "" || claimID == "" || len(csrDER)==0 {
  return ErrInvalid
 }
 if _,err:=identity.ValidateCSR(csrDER);err!=nil{return err}
 digest:=sha256.Sum256([]byte(token))
 csrHash:=sha256.Sum256(csrDER)
 tx,err:=s.DB.BeginTx(ctx,&sql.TxOptions{Isolation:sql.LevelReadCommitted})
 if err!=nil{return err}
 defer tx.Rollback()

 // Only one concurrent transaction can consume this token. Any downstream
 // INSERT failure causes rollback of the consumption too.
 var tokenID string
 err=tx.QueryRowContext(ctx,`UPDATE enrollment_tokens t
 SET consumed_at = now()
 FROM projects p
 WHERE t.project_id = p.id
 AND p.id = $2 AND p.status = 'active'
 AND t.token_digest = $1
 AND t.consumed_at IS NULL AND t.expires_at > now()
 RETURNING t.id`,digest[:],projectID).Scan(&tokenID)
 if errors.Is(err,sql.ErrNoRows){return ErrInvalid}
 if err!=nil{return fmt.Errorf("consume token: %w",err)}

 // A client certificate must not be created until CSR proof-of-possession
 // has been checked by the enrollment coordinator (not implemented here).
 _,err=tx.ExecContext(ctx,`INSERT INTO agents(id,project_id,state)
 VALUES ($1,$2,'pending')`,agentID,projectID)
 if err!=nil{return fmt.Errorf("reserve agent: %w",err)}
 _,err=tx.ExecContext(ctx,`INSERT INTO enrollment_claims
 (id,token_id,project_id,agent_id,csr_sha256,state)
 VALUES ($1,$2,$3,$4,$5,'pending')`,
 claimID,tokenID,projectID,agentID,csrHash[:])
 if err!=nil{return fmt.Errorf("reserve claim: %w",err)}
 return tx.Commit()
}

// FindClaim is a status-only lookup to enable authorized recovery workflows.
// It never returns secrets or signs certificates.
func (s SQLStore) FindClaim(ctx context.Context, claimID string) (string,error){
 if s.DB==nil {return "",errors.New("nil database")}
 if claimID==""{return "",ErrInvalid}
 var state string
 err:=s.DB.QueryRowContext(ctx,`SELECT state FROM enrollment_claims WHERE id=$1`,claimID).Scan(&state)
 return state,err
}
